use crate::model::{Entry,ScanResult};
use serde::{Serialize,Deserialize};
use serde_json::{Value,json};
use std::{collections::HashMap,path::{Path,PathBuf},sync::{Arc,atomic::{AtomicBool,Ordering}},fs};
#[derive(Clone)] pub struct Job {pub request_id:u64,pub token:Arc<AtomicBool>,pub started:std::time::Instant}
#[derive(Default,Serialize,Deserialize)] pub struct Session {pub request_id:u64,pub result:ScanResult,#[serde(default)] pub done:bool,#[serde(default)] pub outcome:String,#[serde(default)] pub progress_text:String,#[serde(default)] pub started_at_ms:u64,#[serde(default)] pub elapsed_ms:u64,#[serde(skip)] pub category:String,#[serde(skip)] pub query:String,#[serde(skip)] pub page:usize,#[serde(skip)] pub removed:Vec<String>,#[serde(skip)] pub removed_snapshots:Vec<Entry>}
#[derive(Default)] pub struct Sessions {pub items:HashMap<String,Session>,pub jobs:HashMap<String,Job>}
pub fn matches(e:&Entry,category:&str,query:&str)->bool {(category=="all"||category.is_empty()||e.kind==category||category=="file"&&e.kind=="large")&&(query.is_empty()||e.name.to_lowercase().contains(&query.to_lowercase())||e.path.to_lowercase().contains(&query.to_lowercase()))}
impl Sessions {
 pub fn start(&mut self,module:&str,id:u64)->Arc<AtomicBool>{if let Some(old)=self.jobs.remove(module){old.token.store(true,Ordering::SeqCst)}let token=Arc::new(AtomicBool::new(false));self.jobs.insert(module.into(),Job{request_id:id,token:token.clone(),started:std::time::Instant::now()});self.items.insert(module.into(),Session{request_id:id,outcome:"running".into(),started_at_ms:std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).unwrap_or_default().as_millis() as u64,..Default::default()});token}
 pub fn current(&self,module:&str,id:u64)->bool{self.jobs.get(module).is_some_and(|j|j.request_id==id)}
 pub fn cancel(&self,module:&str){if let Some(j)=self.jobs.get(module){j.token.store(true,Ordering::SeqCst)}}
 pub fn cancel_all(&self){for j in self.jobs.values(){j.token.store(true,Ordering::SeqCst)}}
 pub fn update(&mut self,module:&str,id:u64,result:ScanResult,done:bool)->bool{if !self.current(module,id){return false}let s=self.items.entry(module.into()).or_default();s.request_id=id;let mut result=result;result.entries.retain(|e|!s.removed.iter().any(|p|e.path==*p||Path::new(&e.path).starts_with(p)));s.result=result;s.done=done;if let Some(job)=self.jobs.get(module){s.elapsed_ms=job.started.elapsed().as_millis() as u64;if done{s.outcome=if job.token.load(Ordering::SeqCst){"cancelled"}else if s.result.skipped>0||s.result.truncated{"partial"}else{"completed"}.into();}}if done{self.jobs.remove(module);}true}
 pub fn progress(&mut self,module:&str,id:u64,text:&str)->bool{if !self.current(module,id)||self.jobs[module].token.load(Ordering::SeqCst){return false}let s=self.items.get_mut(module).unwrap();s.progress_text=text.into();s.elapsed_ms=self.jobs[module].started.elapsed().as_millis() as u64;true}
 pub fn fail(&mut self,module:&str,id:u64,text:&str)->bool{if !self.current(module,id){return false}let s=self.items.get_mut(module).unwrap();s.done=true;s.outcome="failed".into();s.progress_text=text.into();s.result.notes.push(text.into());s.elapsed_ms=self.jobs[module].started.elapsed().as_millis() as u64;self.jobs.remove(module);true}
 pub fn selected(&self,module:&str,category:&str,query:&str)->Vec<Entry>{self.items.get(module).map(|s|s.result.entries.iter().filter(|e|matches(e,category,query)).cloned().collect()).unwrap_or_default()}
 pub fn page(&mut self,module:&str,filter:Option<(&str,&str,usize)>)->Value{let running=self.jobs.contains_key(module);let elapsed=self.jobs.get(module).map(|j|j.started.elapsed().as_millis() as u64);let s=self.items.entry(module.into()).or_default();if let Some((c,q,p))=filter{s.category=c.into();s.query=q.into();s.page=p;}let selected:Vec<_>=s.result.entries.iter().filter(|e|matches(e,&s.category,&s.query)).collect();let count=selected.len();let pages=count.div_ceil(50).max(1);s.page=s.page.min(pages-1);let ignored=crate::safety::load_ignored_paths();let selectable=selected.iter().filter(|e|ignored.as_ref().is_ok_and(|paths|crate::safety::selection_protection_reason(Path::new(&e.path),paths).is_none())).count();let entries:Vec<Value>=selected.iter().skip(s.page*50).take(50).map(|e|{let mut v=serde_json::to_value(e).unwrap();crate::safety::annotate_protection(&mut v,&ignored);v}).collect();json!({"entries":entries,"selectable_total":selectable,"protected_total":count-selectable,"total":s.result.entries.len(),"filtered_total":count,"page":s.page,"page_count":pages,"page_size":50,"total_bytes":s.result.entries.iter().map(|e|e.size).sum::<u64>(),"filtered_bytes":selected.iter().map(|e|e.size).sum::<u64>(),"scanned":s.result.scanned,"skipped":s.result.skipped,"notes":s.result.notes,"truncated":s.result.truncated,"done":s.done,"running":running,"outcome":s.outcome,"progress_text":s.progress_text,"started_at_ms":s.started_at_ms,"elapsed_ms":elapsed.unwrap_or(s.elapsed_ms),"category":s.category,"query":s.query})}
 pub fn remove_paths(&mut self,paths:&[String]){for s in self.items.values_mut(){s.removed_snapshots.extend(s.result.entries.iter().filter(|e|paths.iter().any(|p|e.path==*p||Path::new(&e.path).starts_with(p))).cloned());s.removed.extend_from_slice(paths);s.result.entries.retain(|e|!paths.iter().any(|p|e.path==*p||Path::new(&e.path).starts_with(Path::new(p))));}}
 pub fn restore_paths(&mut self,paths:&[String]){for s in self.items.values_mut(){let returned:Vec<_>=s.removed_snapshots.iter().filter(|e|paths.iter().any(|p|e.path==*p||Path::new(&e.path).starts_with(p))).cloned().collect();for e in returned{if !s.result.entries.iter().any(|old|old.path==e.path){s.result.entries.push(e)}}s.result.entries.sort_by(|a,b|b.size.cmp(&a.size));s.removed.retain(|p|!paths.contains(p));s.removed_snapshots.retain(|e|!paths.iter().any(|p|e.path==*p||Path::new(&e.path).starts_with(p)));}}
 pub fn save(&self,path:&Path)->Result<(),String>{if path.exists(){Self::load(path)?;}crate::schedule::atomic_json(path,&self.items)}
 pub fn load(path:&Path)->Result<HashMap<String,Session>,String>{use std::os::unix::fs::MetadataExt;crate::schedule::safe_path(path)?;let meta=fs::symlink_metadata(path).map_err(|e|e.to_string())?;if !meta.is_file()||meta.uid()!=unsafe{libc::getuid()}{return Err("扫描快照归属或类型无效".into())}let mut values:HashMap<String,Session>=serde_json::from_slice(&fs::read(path).map_err(|e|e.to_string())?).map_err(|e|e.to_string())?;values.retain(|m,_|["smart","junk","large","uninstall"].contains(&m.as_str()));for s in values.values_mut(){s.result.entries.retain(|e|PathBuf::from(&e.path).is_absolute()&&e.id==e.path);if !s.done{s.outcome="interrupted".into();s.result.notes.push("上次扫描未结束；已保留读取结果，请重新扫描以取得完整结果。".into());}else if s.outcome.is_empty(){s.outcome=if s.result.notes.iter().any(|n|n.contains("扫描已取消")){"cancelled"}else if s.result.skipped>0||s.result.truncated{"partial"}else{"completed"}.into();}s.done=true;}Ok(values)}
}
#[cfg(test)]mod tests{
 use super::*;
 fn entry(n:usize,kind:&str)->Entry{Entry{id:format!("/tmp/owned-{n}"),path:format!("/tmp/owned-{n}"),name:format!("owned-{n}"),kind:kind.into(),size:10,modified:None,detail:String::new(),is_dir:false,scope_root:"/tmp".into(),inode:1,device:1,mtime_nsec:0}}
 #[test]fn module_jobs_are_independent(){let mut s=Sessions::default();let a=s.start("junk",1);let b=s.start("large",2);assert!(!a.load(Ordering::SeqCst));s.cancel("large");assert!(b.load(Ordering::SeqCst));assert!(!a.load(Ordering::SeqCst));let _=s.start("junk",3);assert!(a.load(Ordering::SeqCst));assert!(!s.current("junk",1));}
 #[test]fn pages_explain_protection_without_hiding_candidates(){let mut s=Sessions::default();s.start("large",1);let mut entries:Vec<_>=(0..61).map(|n|entry(n,"file")).collect();entries[0].path="/tmp/fixture-data.sqlite".into();entries[0].id=entries[0].path.clone();s.update("large",1,ScanResult{entries,..Default::default()},true);let p=s.page("large",None);assert_eq!(p["filtered_total"],61);assert_eq!(p["selectable_total"],60);assert_eq!(p["protected_total"],1);assert_eq!(p["entries"][0]["protected"],true);assert!(p["entries"][0]["protection_reason"].as_str().unwrap().contains("数据库"));assert_eq!(s.page("large",Some(("all","",1)))["entries"].as_array().unwrap().len(),11);}
 #[test]fn filtering_and_paging_preserve_all_candidates(){let mut s=Sessions::default();s.start("junk",1);s.update("junk",1,ScanResult{entries:(0..123).map(|n|entry(n,if n%2==0{"cache"}else{"log"})).collect(),..Default::default()},true);let p=s.page("junk",Some(("cache","",1)));assert_eq!(p["entries"].as_array().unwrap().len(),12);assert_eq!(p["filtered_total"],62);assert_eq!(s.selected("junk","cache","").len(),62);assert_eq!(s.items["junk"].result.entries.len(),123);}
 #[test]fn moved_paths_cannot_reappear_from_running_scan(){let mut s=Sessions::default();s.start("junk",1);s.start("large",2);let r=ScanResult{entries:vec![entry(1,"cache")],..Default::default()};s.update("junk",1,r.clone(),false);s.update("large",2,r.clone(),false);s.remove_paths(&["/tmp/owned-1".into()]);s.update("junk",1,r,false);assert!(s.items.values().all(|v|v.result.entries.is_empty()));}
 #[test]fn cancelled_scan_is_terminal_and_preserves_partial_candidates(){let mut s=Sessions::default();s.start("junk",1);s.cancel("junk");s.update("junk",1,ScanResult{entries:vec![entry(1,"cache")],..Default::default()},true);let p=s.page("junk",None);assert_eq!(p["running"],false);assert_eq!(p["outcome"],"cancelled");assert_eq!(p["total"],1);}
 #[test]fn failed_worker_releases_job_and_cannot_fail_its_replacement(){let mut s=Sessions::default();s.start("large",1);s.update("large",1,ScanResult{entries:vec![entry(1,"large")],..Default::default()},false);assert!(s.fail("large",1,"读取异常"));let p=s.page("large",None);assert_eq!(p["running"],false);assert_eq!(p["outcome"],"failed");assert_eq!(p["total"],1);s.start("large",2);assert!(!s.fail("large",1,"过时异常"));assert!(s.current("large",2));}
 #[test]fn progress_is_queryable_after_page_switch_and_does_not_reset_clock(){let mut s=Sessions::default();s.start("junk",5);let at=s.items["junk"].started_at_ms;assert!(at>0);assert!(s.progress("junk",5,"已检查 512 项"));s.start("large",6);let p=s.page("junk",None);assert_eq!(p["progress_text"],"已检查 512 项");assert_eq!(p["started_at_ms"],at);assert_eq!(p["running"],true);assert!(!s.progress("junk",4,"旧进度"));}
 #[test]fn unreadable_items_are_not_reported_as_complete_coverage(){let mut s=Sessions::default();s.start("junk",1);s.update("junk",1,ScanResult{skipped:1,..Default::default()},true);assert_eq!(s.page("junk",None)["outcome"],"partial");}
 #[test]fn owned_snapshot_roundtrip_and_corruption_preserved(){let root=fs::canonicalize(std::env::temp_dir()).unwrap().join(format!("karuo-session-test-{}",std::process::id()));fs::create_dir_all(&root).unwrap();let path=root.join("snapshot.json");let mut s=Sessions::default();s.start("junk",9);s.update("junk",9,ScanResult{entries:vec![entry(1,"cache")],..Default::default()},true);s.save(&path).unwrap();assert_eq!(Sessions::load(&path).unwrap()["junk"].result.entries.len(),1);fs::write(&path,b"broken").unwrap();assert!(s.save(&path).is_err());assert_eq!(fs::read(&path).unwrap(),b"broken");fs::remove_dir_all(root).unwrap();}
}
